import json,html,base64,io,hashlib
from pathlib import Path
import pypdfium2 as pdfium
r=Path('data/text_quality/20261111');frozen=r/'frozen_benchmark';out=r/'human_benchmark';out.mkdir(exist_ok=False)
sample=json.loads((frozen/'benchmark_sample.json').read_text());source=Path('question_paper (1).pdf');pdf=pdfium.PdfDocument(str(source));pics={};hashes={}
needed=sorted({n for s in sample['sample_pages'] for n in [s['pdf_page']-1,s['pdf_page'],s['pdf_page']+1] if 1<=n<=len(pdf)})
for n in needed:
 p=pdf[n-1];im=p.render(scale=1.7).to_pil().convert('RGB');buf=io.BytesIO();im.save(buf,format='JPEG',quality=87);raw=buf.getvalue();pics[str(n)]=base64.b64encode(raw).decode();hashes[str(n)]=hashlib.sha256(raw).hexdigest();p.close()
pdf.close()
data=json.dumps({'sample':sample['sample_pages'],'images':pics}).replace('<','\\u003c')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Blind human extraction benchmark</title><style>body{font:16px/1.5 system-ui;max-width:1100px;margin:20px auto;padding:15px}img{width:100%}textarea{width:100%;min-height:220px;font:14px monospace}input,select,button{font:inherit;padding:6px;margin:5px}pre{white-space:pre-wrap}.bar{position:sticky;top:0;background:#fff;padding:8px;border:1px solid #aaa}</style><h1>Blind human extraction benchmark</h1><p>Prepared 11 November 2026. Frozen sample: 60 pages, 12 year/method strata, seed 20261111. This packet contains source images only; no extraction or Luna proposal is shown. Use two separate copies for independent reviewers. Do not compare readings until both are frozen. Save decisions before closing: entries are held only in this browser session.</p><p>For each sampled page transcribe every visible question start, option label/text, passage boundary and continuation. Include items missing from machine extraction. Distinguish starts on this page from continuations using adjacent pages. Preserve punctuation, spelling, numbers, source typos and unreadable spans; do not silently repair wording. Check negation, dates, article/section numbers, case names and citations explicitly. Images from adjacent pages are context only. Record printed page if visible.</p><p>References require two independent readings plus adjudication before accuracy can be measured. No accuracy result or corpus completeness claim is implied by this sample. Source material stays local; rights remain unconfirmed.</p><div class="bar"><label>Reviewer <input id="reviewer"></label><label>Review date <input id="date" type="date"></label><select id="choose"></select><button id="download">Download reading (.jsonl)</button></div><h2 id="heading"></h2><label>Structured source reading<textarea id="reading" placeholder="Enter JSON using the schema below; include all visible starts and continuations."></textarea></label><pre>{"printed_page": null, "question_starts": [{"local_id":"pNNN-q1","printed_question_number":null,"stem":"literal source","options":[{"label":"A","text":"literal source"}],"critical_tokens":[],"uncertainties":[]}], "continuations":[], "passage_boundaries":[], "unreadable_regions":[], "notes":""}</pre><div id="images"></div><script>const DATA=REPLACE_DATA;const readings={};let active=null;const choose=document.getElementById('choose');const input=document.getElementById('reading');for(const s of DATA.sample){const o=document.createElement('option');o.value=s.sample_id;o.textContent=s.sample_id+' | '+s.year_label+' | PDF '+s.pdf_page;choose.appendChild(o);}function show(){if(active)readings[active]=input.value;active=choose.value;const s=DATA.sample.find(x=>x.sample_id===active);document.getElementById('heading').textContent=s.sample_id+' | '+s.year_label+' | PDF page '+s.pdf_page+' | '+s.method;input.value=readings[active]||'';const target=document.getElementById('images');target.replaceChildren();for(const n of [s.pdf_page,s.pdf_page-1,s.pdf_page+1]){if(!DATA.images[n])continue;const panel=document.createElement('details');panel.open=n===s.pdf_page;const title=document.createElement('summary');title.textContent=(n===s.pdf_page?'SAMPLED PAGE: ':'Context only: ')+'PDF '+n;const im=document.createElement('img');im.alt='Source PDF page '+n;im.src='data:image/jpeg;base64,'+DATA.images[n];panel.append(title,im);target.append(panel);}}choose.onchange=show;document.getElementById('download').onclick=()=>{readings[active]=input.value;const rows=[];for(const s of DATA.sample){let annotation=null;const raw=readings[s.sample_id]||'';if(raw){try{annotation=JSON.parse(raw)}catch(e){alert('Invalid JSON for '+s.sample_id+'. Fix it before export.');return;}}rows.push({...s,reviewer:document.getElementById('reviewer').value||null,review_date:document.getElementById('date').value||null,reading:annotation,reference_status:annotation?'independent_reading_pending_adjudication':'blank_unreviewed'});}const blob=new Blob([rows.map(x=>JSON.stringify(x)).join('\\n')+'\\n'],{type:'application/x-ndjson'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='independent_human_reading.jsonl';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};show();</script></html>'''.replace('REPLACE_DATA',data)
(out/'blind_review.html').write_text(page,encoding='utf8')
(out/'manifest.json').write_text(json.dumps({'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'sample_manifest_sha256':hashlib.sha256((frozen/'benchmark_sample.json').read_bytes()).hexdigest(),'sampled_pages':60,'embedded_context_and_sample_pages':len(needed),'image_sha256':hashes,'html_sha256':hashlib.sha256((out/'blind_review.html').read_bytes()).hexdigest(),'gold_status':'not_created'},indent=2),encoding='utf8')
print('Built blind packet',len(needed),'embedded pages',round((out/'blind_review.html').stat().st_size/1e6,1),'MB')
